import{c as d,Q as e,j as a,m as I}from"./chunks/framework.DOi4mjdC.js";const o=JSON.parse('{"title":"Ascend C API列表","description":"","frontmatter":{},"headers":[{"level":1,"title":"Ascend C API列表","slug":"ascend-c-api列表"},{"level":2,"title":"API分类总览","slug":"api分类总览"}],"relativePath":"api/Ascend-C-API列表.md","filePath":"api/Ascend-C-API列表.md"}'),A={name:"api/Ascend-C-API列表.md"};function r(P,t,n,c,s,i){return e(),a("div",null,[...t[0]||(t[0]=[I('<h1 id="ascend-c-api列表" tabindex="-1">Ascend C API列表 <a class="header-anchor" href="#ascend-c-api列表" aria-label="Permalink to &quot;Ascend C API列表&quot;">​</a></h1><p>Ascend C 提供了一套层次化的 API 体系，涵盖了从底层 C 扩展到高阶 C++ 类库的完整能力。它支持开发者以标准 C/C++ 语法为基础，在 AI Core(SIMD/SIMT) 及 AI CPU 等多种编程模型下，灵活实现精细化的内存管理与高效的矢量/矩阵运算。</p><h2 id="api分类总览" tabindex="-1">API分类总览 <a class="header-anchor" href="#api分类总览" aria-label="Permalink to &quot;API分类总览&quot;">​</a></h2><p>下表展示了 Ascend C API 的总体分类，帮助开发者根据编程模型和功能需求快速定位所需API。</p><table tabindex="0"><thead><tr><th>API一级分类</th><th>API二级分类</th><th>分类说明</th></tr></thead><tbody><tr><td>SIMD API</td><td>基础API</td><td>实现对硬件能力的抽象，开放芯片的能力，保证完备性和兼容性。标注为ISASI（Instruction Set Architecture Special Interface，硬件体系结构相关的接口）类别的API，不能保证跨硬件版本兼容。</td></tr><tr><td>SIMD API</td><td>C API</td><td>纯C接口，开放芯片完备编程能力，支持数组分配内存，一般基于指针编程，提供与业界一致的C语言编程体验。</td></tr><tr><td>SIMD API</td><td>高阶 API</td><td>实现一些常用的计算算法，用于提高编程开发效率，通常会调用多种基础API实现。高阶API包括数学库、Matmul、Softmax等API。高阶API可以保证兼容性。</td></tr><tr><td>SIMT API</td><td>-</td><td>对标业界，提供单指令多线程API。以单条指令多个线程的形式来实现并行计算。SIMT编程主要用于向量计算，特别适合处理离散访问、复杂控制逻辑等场景。SIMT API支持两种编程模型：SIMT编程、SIMD与SIMT混合编程，具体支持的API请分别参见SIMT编程API列表、SIMD与SIMT混合编程API列表。</td></tr><tr><td>AI CPU API</td><td>-</td><td>通常作为上述API的补充，主要承担非矩阵类、逻辑比较复杂的分支密集型计算。</td></tr><tr><td>Utils API</td><td>-</td><td>丰富的通用工具类，涵盖标准库（目前仅支持SIMD）、平台信息获取、运行时编译及日志输出等功能，支持开发者高效实现算子开发与性能优化。</td></tr></tbody></table>',5)])])}const p=d(A,[["render",r]]);export{o as __pageData,p as default};
